export function journalLedger(initialBalance,entries){if(!Number.isFinite(initialBalance)||initialBalance<=0)throw Error('Invalid starting balance');let balance=initialBalance,blocked=false;return Array.from({length:100},(_,i)=>{const e=entries[i]||{},buy=Number(e.buy),sell=Number(e.sell),hasBuy=e.buy!==''&&e.buy!=null,hasSell=e.sell!==''&&e.sell!=null,valid=String(e.coin||'').trim()&&hasBuy&&hasSell&&Number.isFinite(buy)&&buy>0&&Number.isFinite(sell)&&sell>=0;const start=balance;if(balance<=0)blocked=true;if(blocked||!valid){const locked=blocked;blocked=true;return {number:i+1,entry:e,locked,closed:false,startBalance:locked?null:start,endingBalance:null,profitPct:null,pnl:null};}const profitPct=(sell/buy-1)*100,pnl=start*profitPct/100;balance=start+pnl;return {number:i+1,entry:e,locked:false,closed:true,startBalance:start,endingBalance:balance,profitPct,pnl};});}
